y,x=np.mgrid[0:20,0:20]
z=1-C

def pred_spiral(par,metric='euclid'):
 cx,cy,k,phase=par
 dx=x-cx;dy=y-cy
 if metric=='euclid':r=np.hypot(dx,dy)
 elif metric=='l1':r=np.abs(dx)+np.abs(dy)
 else:r=np.maximum(np.abs(dx),np.abs(dy))
 th=np.arctan2(dy,dx)
 return ((np.floor(r+k*th+phase)%2).astype(int))
